// ─────────────────────────────────────────────────────────────────────────────
// PHOTOS — real photographs from Urgent Plumbing & Drainage jobs.
//
// No stock or AI-generated images. Every photo below was checked by eye before publishing:
// alt text and captions describe only what can actually be seen (no invented customers,
// places, dates or prices). Source files live in /public/images/work/.
//
// To add a photo: put the file in /public/images/work/, add an entry below with its pixel
// size, and reference its id in the placements at the bottom of this file.
//
// NOT PUBLISHED (kept out of /public on purpose, so they aren't reachable online):
//  - Boiler with its casing open (Grundfos pump, heat exchanger): gas appliance work needs Gas
//    Safe registration, which the site doesn't claim. Add only once that's confirmed.
//  - Unvented hot water cylinder (Joule) with expansion vessels: unvented cylinders need a G3
//    qualification. A very good photo — add it to the hot water page once that's confirmed.
//  - Pressure-reducing valve beside a cylinder: dim, and may be part of an unvented set-up.
//  - Van with "24/7 Emergency Service" livery: appears to be a computer-generated mock-up
//    (non-UK house, no number plate, livery differs from the real logo), not a photograph.
//  - Vanity basin with the customer's toiletries and ornaments on show; a second vanity basin
//    with someone's arm in the frame; corroded pipework where before/after isn't clear.
// ─────────────────────────────────────────────────────────────────────────────

export type PhotoCategory = "team" | "drainage" | "pipework" | "fittings" | "hot-water" | "other";

export interface Photo {
  src: string;
  width: number;
  height: number;
  category: PhotoCategory;
  /** CSS object-position used when the photo is cropped to a different shape. */
  focus: string;
  alt: string;
  caption: string;
  /** Tiny inline preview shown while the photo loads. */
  blur: string;
}

